"use client";

import * as React from "react";

import { KbSpreadsheets } from "@/components/mockups/kb-spreadsheets/kb-spreadsheets";
import { ReviewerSwitch } from "@/components/shared/reviewer-switch";
import { MockupShell } from "@/components/shell/mockup-shell";

const VIEWS = [
  { id: "base", label: "Knowledge base", open: null },
  { id: "sheet", label: "Editing a file", open: "src-xlsx-1" },
  { id: "near", label: "Near the limit", open: "src-xlsx-2" },
] as const;

export default function KbSpreadsheetsPage() {
  const [openId, setOpenId] = React.useState<string | null>(null);
  const view = VIEWS.find((entry) => entry.open === openId)?.id ?? "base";

  return (
    <div className="flex h-svh flex-col">
      <MockupShell
        title="Client-maintained knowledge base files"
        actions={
          <ReviewerSwitch
            label="View"
            onChange={(next) => {
              const entry = VIEWS.find((item) => item.id === next);
              if (entry) setOpenId(entry.open);
            }}
            options={VIEWS}
            value={view}
          />
        }
      >
        <KbSpreadsheets openId={openId} onOpenChange={setOpenId} />
      </MockupShell>
    </div>
  );
}

"use client";

import {
  ArrowLeft01Icon,
  Delete02Icon,
  PlusSignIcon,
} from "@hugeicons/core-free-icons";

import { icon } from "@/components/shared/icon";

export {
  AddFilterIcon,
  DownloadIcon,
  FailedIcon,
  KnowledgeIcon,
  ReadyIcon,
  RemoveIcon,
  SearchIcon,
  SortIcon,
} from "@/components/mockups/knowledge-base/icons";

export const BackIcon = icon(ArrowLeft01Icon, "BackIcon");
export const AddRowIcon = icon(PlusSignIcon, "AddRowIcon");
export const DeleteRowIcon = icon(Delete02Icon, "DeleteRowIcon");

"use client";

import * as React from "react";

import { KnowledgeBaseDetail } from "@/components/mockups/kb-spreadsheets/knowledge-base-detail";
import { SheetEditor } from "@/components/mockups/kb-spreadsheets/sheet-editor";
import { SOURCES, type Source } from "@/lib/mockups/kb-spreadsheets-data";

export function KbSpreadsheets({
  openId,
  onOpenChange,
}: {
  openId: string | null;
  onOpenChange: (id: string | null) => void;
}) {
  const [sources, setSources] = React.useState<Source[]>(() => [...SOURCES]);
  const open = sources.find((source) => source.id === openId);

  if (open?.sheet && open.tokens !== undefined) {
    return (
      <SheetEditor
        key={open.id}
        source={{ ...open, sheet: open.sheet, tokens: open.tokens }}
        onBack={() => onOpenChange(null)}
        onSave={(sheet, tokens) =>
          setSources((current) =>
            current.map((source) =>
              source.id === open.id
                ? { ...source, sheet, tokens, addedAt: "Just now" }
                : source,
            ),
          )
        }
      />
    );
  }

  return (
    <KnowledgeBaseDetail
      sources={sources}
      setSources={setSources}
      onOpenSheet={onOpenChange}
    />
  );
}

"use client";

import * as React from "react";
import { toast } from "sonner";

import {
  AddFilterIcon,
  KnowledgeIcon,
  SearchIcon,
  SortIcon,
} from "@/components/mockups/kb-spreadsheets/icons";
import { SourceTable } from "@/components/mockups/kb-spreadsheets/source-table";
import {
  AddSourceDialog,
  AddSources,
  type AddKind,
} from "@/components/mockups/knowledge-base/add-sources";
import { SummaryField } from "@/components/mockups/knowledge-base/summary-field";
import { PageHeader } from "@/components/shared/page-header";
import { AppShell } from "@/components/shell/app-shell";
import { Button } from "@/components/ui/button";
import { Card, CardContent } from "@/components/ui/card";
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuRadioGroup,
  DropdownMenuRadioItem,
  DropdownMenuTrigger,
} from "@/components/ui/dropdown-menu";
import {
  Empty,
  EmptyHeader,
  EmptyMedia,
  EmptyTitle,
} from "@/components/ui/empty";
import { Input } from "@/components/ui/input";
import {
  InputGroup,
  InputGroupAddon,
  InputGroupInput,
} from "@/components/ui/input-group";
import {
  SOURCE_KINDS,
  SOURCE_LABELS,
  SPREADSHEET_MAX_BYTES,
  isSpreadsheet,
  parsedSheet,
  pendingSource,
  type Source,
  type SourceKind,
} from "@/lib/mockups/kb-spreadsheets-data";
import { KNOWLEDGE_BASE } from "@/lib/mockups/knowledge-base-data";

export function KnowledgeBaseDetail({
  base = KNOWLEDGE_BASE,
  sources,
  setSources,
  onOpenSheet,
}: {
  base?: typeof KNOWLEDGE_BASE;
  sources: Source[];
  setSources: React.Dispatch<React.SetStateAction<Source[]>>;
  onOpenSheet: (id: string) => void;
}) {
  const [dialog, setDialog] = React.useState<AddKind | null>(null);
  const [query, setQuery] = React.useState("");
  const [kind, setKind] = React.useState<SourceKind | "all">("all");
  const [creator, setCreator] = React.useState<string>("all");
  const [sort, setSort] = React.useState<SortKey>("added");

  const filePicker = React.useRef<HTMLInputElement>(null);

  const creators = [...new Set(sources.map((source) => source.addedBy))];

  const matched = sources.filter(
    (source) =>
      (kind === "all" || source.kind === kind) &&
      (creator === "all" || source.addedBy === creator) &&
      `${source.name} ${source.url ?? ""}`
        .toLowerCase()
        .includes(query.trim().toLowerCase()),
  );
  const visible =
    sort === "title"
      ? matched.toSorted((a, b) => a.name.localeCompare(b.name))
      : matched;

  function openAdd(next: AddKind) {
    if (next === "files") {
      filePicker.current?.click();
      return;
    }
    setDialog(next);
  }

  function addTyped(
    next: AddKind,
    source: { name: string; url?: string; body?: string },
  ) {
    setSources((current) => [
      {
        id: `src-${String(current.length + 1)}-${source.name}`,
        name: source.name,
        kind: next === "url" ? "url" : "text",
        url: source.url,
        body: source.body,
        status: "ready",
        size: "—",
        addedBy: "talzamel@sarj.ai",
        addedAt: "Just now",
      },
      ...current,
    ]);
  }

  function addFiles(files: FileList | null) {
    if (!files?.length) return;

    const picked = [...files].map((file, index) =>
      pendingSource(
        `src-file-${String(Date.now())}-${String(index)}`,
        file.name,
        `${String(Math.max(1, Math.round(file.size / 1024)))} KB`,
      ),
    );
    const tooBig = picked.filter(
      (source, index) =>
        isSpreadsheet(source.kind) &&
        (files.item(index)?.size ?? 0) > SPREADSHEET_MAX_BYTES,
    );
    for (const source of tooBig) {
      toast.error(`${source.name} not added`, {
        description: "Choose a spreadsheet up to 1 MB.",
      });
    }
    const accepted = picked.filter((source) => !tooBig.includes(source));
    if (!accepted.length) return;

    setSources((current) => [...accepted, ...current]);

    window.setTimeout(() => {
      const ids = new Set(accepted.map((source) => source.id));
      setSources((current) =>
        current.map((source) =>
          ids.has(source.id) ? readySource(source) : source,
        ),
      );
    }, 1800);
  }

  return (
    <AppShell
      active="Knowledge Bases"
      breadcrumb={["Knowledge Bases", base.name]}
    >
      <div className="flex flex-col gap-6 p-3 lg:p-4">
        <PageHeader
          title={base.name}
          description={`Last updated ${base.updatedAt} by ${base.updatedBy}`}
          actions={<AddSources onOpen={openAdd} />}
        />

        <Input
          ref={filePicker}
          type="file"
          multiple
          accept=".pdf,.docx,.txt,.md,.xlsx,.csv"
          className="hidden"
          onChange={(event) => {
            addFiles(event.target.files);
            event.target.value = "";
          }}
        />

        <Card>
          <CardContent>
            <SummaryField value={base.summary} />
          </CardContent>
        </Card>

        <section className="flex flex-col gap-2">
          <div className="flex items-center gap-2">
            <InputGroup>
              <InputGroupAddon>
                <SearchIcon />
              </InputGroupAddon>
              <InputGroupInput
                value={query}
                onChange={(event) => setQuery(event.target.value)}
                placeholder="Search by name..."
                aria-label="Search files by name"
              />
            </InputGroup>

            <DropdownMenu modal={false}>
              <DropdownMenuTrigger asChild>
                <Button variant="outline" aria-label="Sort">
                  <SortIcon />
                  {SORT_LABELS[sort]}
                </Button>
              </DropdownMenuTrigger>
              <DropdownMenuContent align="end">
                <DropdownMenuRadioGroup
                  value={sort}
                  onValueChange={(next) => {
                    const match = SORT_KEYS.find((item) => item === next);
                    if (match) setSort(match);
                  }}
                >
                  {SORT_KEYS.map((item) => (
                    <DropdownMenuRadioItem key={item} value={item}>
                      {SORT_LABELS[item]}
                    </DropdownMenuRadioItem>
                  ))}
                </DropdownMenuRadioGroup>
              </DropdownMenuContent>
            </DropdownMenu>
          </div>

          <div className="flex flex-wrap gap-2">
            <FilterChip
              field="Type"
              value={kind}
              options={SOURCE_KINDS.map((item) => ({
                value: item,
                label: SOURCE_LABELS[item],
              }))}
              onChange={(next) =>
                setKind(SOURCE_KINDS.find((item) => item === next) ?? "all")
              }
            />
            <FilterChip
              field="Creator"
              value={creator}
              options={creators.map((item) => ({ value: item, label: item }))}
              onChange={setCreator}
            />
          </div>
        </section>

        {visible.length ? (
          <Card className="[--card-spacing:0px]">
            <div className="overflow-x-auto">
              <SourceTable
                sources={visible}
                onOpenSheet={onOpenSheet}
                onRemove={(id) =>
                  setSources((current) =>
                    current.filter((source) => source.id !== id),
                  )
                }
              />
            </div>
          </Card>
        ) : (
          <Empty className="border border-solid bg-muted/50">
            <EmptyHeader>
              <EmptyMedia
                variant="icon"
                className="size-10 border bg-background"
              >
                <KnowledgeIcon />
              </EmptyMedia>
              <EmptyTitle>
                {sources.length
                  ? query.trim()
                    ? `No files match “${query.trim()}”`
                    : "No files match these filters"
                  : "No files yet"}
              </EmptyTitle>
            </EmptyHeader>
          </Empty>
        )}

        <AddSourceDialog
          kind={dialog}
          onOpenChange={(open) => setDialog(open ? dialog : null)}
          onAdd={addTyped}
        />
      </div>
    </AppShell>
  );
}

function readySource(source: Source): Source {
  if (isSpreadsheet(source.kind)) {
    return { ...source, status: "ready", ...parsedSheet() };
  }
  return { ...source, status: "ready" };
}

type SortKey = "added" | "title";

const SORT_KEYS: readonly SortKey[] = ["added", "title"];

const SORT_LABELS: Record<SortKey, string> = {
  added: "Date added",
  title: "Title",
};

function FilterChip({
  field,
  value,
  options,
  onChange,
}: {
  field: string;
  value: string;
  options: { value: string; label: string }[];
  onChange: (value: string) => void;
}) {
  const chosen = options.find((option) => option.value === value);

  return (
    <DropdownMenu modal={false}>
      <DropdownMenuTrigger asChild>
        <Button variant="outline" size="xs">
          {chosen ? (
            `${field}: ${chosen.label}`
          ) : (
            <>
              <AddFilterIcon />
              {field}
            </>
          )}
        </Button>
      </DropdownMenuTrigger>
      <DropdownMenuContent align="start">
        <DropdownMenuRadioGroup value={value} onValueChange={onChange}>
          <DropdownMenuRadioItem value="all">All</DropdownMenuRadioItem>
          {options.map((option) => (
            <DropdownMenuRadioItem key={option.value} value={option.value}>
              {option.label}
            </DropdownMenuRadioItem>
          ))}
        </DropdownMenuRadioGroup>
      </DropdownMenuContent>
    </DropdownMenu>
  );
}

"use client";

import * as React from "react";
import { toast } from "sonner";

import {
  AddRowIcon,
  BackIcon,
  DeleteRowIcon,
  DownloadIcon,
  FailedIcon,
} from "@/components/mockups/kb-spreadsheets/icons";
import {
  DataTableHead,
  DataTableHeaderRow,
} from "@/components/shared/data-table";
import { SaveBar } from "@/components/shared/save-bar";
import { AppShell } from "@/components/shell/app-shell";
import { Alert, AlertDescription, AlertTitle } from "@/components/ui/alert";
import {
  AlertDialog,
  AlertDialogAction,
  AlertDialogCancel,
  AlertDialogContent,
  AlertDialogDescription,
  AlertDialogFooter,
  AlertDialogHeader,
  AlertDialogTitle,
} from "@/components/ui/alert-dialog";
import { Button } from "@/components/ui/button";
import { Card } from "@/components/ui/card";
import { Input } from "@/components/ui/input";
import { Progress } from "@/components/ui/progress";
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from "@/components/ui/table";
import {
  TOKEN_LIMIT,
  TOKEN_WARNING,
  sheetTokens,
  type Sheet,
  type Source,
} from "@/lib/mockups/kb-spreadsheets-data";
import { KNOWLEDGE_BASE } from "@/lib/mockups/knowledge-base-data";
import { cn } from "@/lib/utils";

interface DraftRow {
  id: string;
  cells: string[];
  original?: string[];
}

function toDraft(sheet: Sheet): DraftRow[] {
  return sheet.rows.map((cells, index) => ({
    id: `row-${String(index)}`,
    cells: [...cells],
    original: cells,
  }));
}

export function SheetEditor({
  source,
  onBack,
  onSave,
}: {
  source: Source & { sheet: Sheet; tokens: number };
  onBack: () => void;
  onSave: (sheet: Sheet, tokens: number) => void;
}) {
  const { sheet } = source;
  const [draft, setDraft] = React.useState(() => toDraft(sheet));
  const [leaving, setLeaving] = React.useState(false);
  const added = React.useRef(0);
  const lastRow = React.useRef<HTMLInputElement>(null);
  const focusNew = React.useRef(false);
  const root = React.useRef<HTMLDivElement>(null);

  React.useEffect(() => {
    root.current?.parentElement?.scrollTo(0, 0);
  }, []);

  const widths = sheet.columns.map((_, index) => {
    const longest = Math.max(
      0,
      ...sheet.rows.map((row) => row[index]?.length ?? 0),
    );
    return longest > 24 ? "min-w-72" : longest > 14 ? "min-w-48" : "min-w-32";
  });

  React.useEffect(() => {
    if (!focusNew.current) return;
    focusNew.current = false;
    lastRow.current?.scrollIntoView({ block: "center" });
    lastRow.current?.focus();
  }, [draft.length]);

  const changes = countChanges(draft, sheet.rows.length);
  const current: Sheet = {
    columns: sheet.columns,
    rows: draft.map((row) => row.cells),
  };
  const tokens = Math.max(
    0,
    source.tokens + sheetTokens(current) - sheetTokens(sheet),
  );
  const over = tokens > TOKEN_LIMIT;
  const near = !over && tokens >= TOKEN_WARNING;

  function edit(rowId: string, column: number, value: string) {
    setDraft((rows) =>
      rows.map((row) =>
        row.id === rowId
          ? {
              ...row,
              cells: row.cells.map((cell, i) => (i === column ? value : cell)),
            }
          : row,
      ),
    );
  }

  function addRow() {
    added.current += 1;
    setDraft((rows) => [
      ...rows,
      {
        id: `new-${String(added.current)}`,
        cells: sheet.columns.map(() => ""),
      },
    ]);
    focusNew.current = true;
  }

  function removeRow(rowId: string) {
    setDraft((rows) => rows.filter((row) => row.id !== rowId));
  }

  function discard() {
    const before = draft;
    setDraft(toDraft(sheet));
    toast("Changes discarded", {
      action: { label: "Undo", onClick: () => setDraft(before) },
    });
  }

  function save() {
    if (over) {
      toast.error("Not saved", {
        description: `The file is over the ${TOKEN_LIMIT.toLocaleString("en-US")}-token limit. Remove some rows first.`,
      });
      return;
    }
    onSave(current, tokens);
    setDraft(toDraft(current));
    toast(`${source.name} saved`);
  }

  function back() {
    if (changes > 0) setLeaving(true);
    else onBack();
  }

  return (
    <AppShell
      active="Knowledge Bases"
      breadcrumb={["Knowledge Bases", KNOWLEDGE_BASE.name, source.name]}
    >
      <div ref={root} className="flex min-h-full flex-col gap-6 p-3 lg:p-4">
        <header className="flex flex-wrap items-start justify-between gap-4">
          <div className="flex items-start gap-2">
            <Button
              aria-label={`Back to ${KNOWLEDGE_BASE.name}`}
              size="icon-sm"
              variant="ghost"
              onClick={back}
            >
              <BackIcon className="rtl:rotate-180" />
            </Button>
            <div className="flex flex-col gap-1">
              <h1 className="text-2xl font-semibold" dir="auto">
                {source.name}
              </h1>
              <p className="text-sm text-muted-foreground">
                {draft.length} rows · {sheet.columns.length} columns
              </p>
            </div>
          </div>

          <div className="flex items-center gap-4">
            <TokenReading tokens={tokens} over={over} near={near} />
            <div className="flex items-center gap-2">
              <Button variant="outline" onClick={addRow}>
                <AddRowIcon />
                Add row
              </Button>
              <Button variant="outline" aria-label={`Download ${source.name}`}>
                <DownloadIcon />
                Download
              </Button>
            </div>
          </div>
        </header>

        {over ? (
          <Alert variant="destructive">
            <FailedIcon />
            <AlertTitle>Over the token limit</AlertTitle>
            <AlertDescription>
              Remove rows or shorten cells to save. A file can be up to{" "}
              {TOKEN_LIMIT.toLocaleString("en-US")} tokens.
            </AlertDescription>
          </Alert>
        ) : null}

        <Card className="[--card-spacing:0px]">
          <div className="overflow-x-auto">
            <Table>
              <TableHeader>
                <DataTableHeaderRow>
                  <DataTableHead className="w-12 text-end">#</DataTableHead>
                  {sheet.columns.map((column) => (
                    <DataTableHead key={column} className="ps-4.5">
                      {column}
                    </DataTableHead>
                  ))}
                  <TableHead className="w-12" />
                </DataTableHeaderRow>
              </TableHeader>

              <TableBody>
                {draft.map((row, rowIndex) => (
                  <TableRow key={row.id}>
                    <TableCell className="text-end text-muted-foreground tabular-nums">
                      {rowIndex + 1}
                    </TableCell>
                    {row.cells.map((cell, column) => {
                      const changed =
                        !row.original || cell !== row.original[column];
                      return (
                        <TableCell
                          key={sheet.columns[column]}
                          className={cn(changed && "bg-primary-tint")}
                        >
                          <Input
                            ref={
                              rowIndex === draft.length - 1 && column === 0
                                ? lastRow
                                : undefined
                            }
                            aria-label={`${sheet.columns[column]}, row ${String(rowIndex + 1)}`}
                            className={cn(
                              widths[column],
                              "border-transparent bg-transparent hover:border-input",
                            )}
                            dir="auto"
                            value={cell}
                            onChange={(event) =>
                              edit(row.id, column, event.target.value)
                            }
                          />
                        </TableCell>
                      );
                    })}
                    <TableCell>
                      <Button
                        aria-label={`Delete row ${String(rowIndex + 1)}`}
                        size="icon-sm"
                        variant="ghost"
                        onClick={() => removeRow(row.id)}
                      >
                        <DeleteRowIcon />
                      </Button>
                    </TableCell>
                  </TableRow>
                ))}
              </TableBody>
            </Table>
          </div>
        </Card>

        <SaveBar changes={changes} onDiscard={discard} onSave={save} />
      </div>

      <AlertDialog open={leaving} onOpenChange={setLeaving}>
        <AlertDialogContent>
          <AlertDialogHeader>
            <AlertDialogTitle>Discard changes?</AlertDialogTitle>
            <AlertDialogDescription>
              {changes === 1 ? "1 change" : `${String(changes)} changes`} to{" "}
              <span dir="auto">{source.name}</span> will be lost. The saved file
              stays as it was.
            </AlertDialogDescription>
          </AlertDialogHeader>
          <AlertDialogFooter>
            <AlertDialogCancel>Cancel</AlertDialogCancel>
            <AlertDialogAction variant="destructive" onClick={onBack}>
              Discard
            </AlertDialogAction>
          </AlertDialogFooter>
        </AlertDialogContent>
      </AlertDialog>
    </AppShell>
  );
}

function countChanges(draft: DraftRow[], originalRows: number): number {
  const kept = draft.filter((row) => row.original);
  const edited = kept.reduce(
    (sum, row) =>
      sum + row.cells.filter((cell, i) => cell !== row.original?.[i]).length,
    0,
  );
  const added = draft.length - kept.length;
  const removed = originalRows - kept.length;
  return edited + added + removed;
}

function TokenReading({
  tokens,
  over,
  near,
}: {
  tokens: number;
  over: boolean;
  near: boolean;
}) {
  return (
    <div className="flex w-44 flex-col gap-1.5">
      <span
        className={cn(
          "text-xs tabular-nums",
          over
            ? "text-destructive"
            : near
              ? "text-warning"
              : "text-muted-foreground",
        )}
      >
        {tokens.toLocaleString("en-US")} of{" "}
        {TOKEN_LIMIT.toLocaleString("en-US")} tokens
      </span>
      <Progress
        aria-label="Token budget used"
        value={Math.min(100, (tokens / TOKEN_LIMIT) * 100)}
      />
    </div>
  );
}

"use client";

import {
  DownloadIcon,
  FailedIcon,
  ReadyIcon,
  RemoveIcon,
} from "@/components/mockups/kb-spreadsheets/icons";
import {
  DataTableHead,
  DataTableHeaderRow,
} from "@/components/shared/data-table";
import {
  AlertDialog,
  AlertDialogAction,
  AlertDialogCancel,
  AlertDialogContent,
  AlertDialogDescription,
  AlertDialogFooter,
  AlertDialogHeader,
  AlertDialogTitle,
  AlertDialogTrigger,
} from "@/components/ui/alert-dialog";
import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogHeader,
  DialogTitle,
  DialogTrigger,
} from "@/components/ui/dialog";
import { Spinner } from "@/components/ui/spinner";
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from "@/components/ui/table";
import {
  SOURCE_LABELS,
  TOKEN_LIMIT,
  TOKEN_WARNING,
  formatTokens,
  isFileSource,
  isSpreadsheet,
  type Source,
} from "@/lib/mockups/kb-spreadsheets-data";
import { sourceHref } from "@/lib/mockups/knowledge-base-data";
import { cn } from "@/lib/utils";

export function SourceTable({
  sources,
  onRemove,
  onOpenSheet,
}: {
  sources: Source[];
  onRemove: (id: string) => void;
  onOpenSheet: (id: string) => void;
}) {
  return (
    <Table>
      <TableHeader>
        <DataTableHeaderRow>
          <DataTableHead>Name</DataTableHead>
          <DataTableHead>Added by</DataTableHead>
          <DataTableHead>Added</DataTableHead>
          <DataTableHead>Status</DataTableHead>
          <TableHead className="w-24" />
        </DataTableHeaderRow>
      </TableHeader>

      <TableBody>
        {sources.map((source) => (
          <TableRow key={source.id}>
            <TableCell>
              <div className="flex min-w-0 flex-col gap-0.5">
                <SourceName source={source} onOpenSheet={onOpenSheet} />
                <SourceDetail source={source} />
              </div>
            </TableCell>

            <TableCell className="text-muted-foreground">
              {source.addedBy}
            </TableCell>

            <TableCell className="text-muted-foreground">
              {source.addedAt}
            </TableCell>

            <TableCell>
              <StatusBadge source={source} />
            </TableCell>

            <TableCell>
              <div className="flex items-center justify-end gap-1">
                {isFileSource(source.kind) ? (
                  <Button
                    variant="ghost"
                    size="icon-sm"
                    aria-label={`Download ${source.name}`}
                  >
                    <DownloadIcon />
                  </Button>
                ) : null}

                <RemoveSource
                  source={source}
                  onRemove={() => onRemove(source.id)}
                />
              </div>
            </TableCell>
          </TableRow>
        ))}
      </TableBody>
    </Table>
  );
}

function SourceDetail({ source }: { source: Source }) {
  if (source.problem) {
    return <span className="text-xs text-destructive">{source.problem}</span>;
  }

  if (isSpreadsheet(source.kind) && source.sheet && source.tokens) {
    const near = source.tokens >= TOKEN_WARNING;
    return (
      <span
        className={cn(
          "text-xs",
          near ? "text-warning" : "text-muted-foreground",
        )}
      >
        {SOURCE_LABELS[source.kind]} · {source.sheet.rows.length} rows ·{" "}
        {formatTokens(source.tokens)} of {formatTokens(TOKEN_LIMIT)} tokens
        {near ? ", near the limit" : ""}
      </span>
    );
  }

  return (
    <span className="text-xs text-muted-foreground">
      {source.url ??
        [SOURCE_LABELS[source.kind], source.size]
          .filter((part) => part && part !== "—")
          .join(" · ")}
    </span>
  );
}

function RemoveSource({
  source,
  onRemove,
}: {
  source: Source;
  onRemove: () => void;
}) {
  return (
    <AlertDialog>
      <AlertDialogTrigger asChild>
        <Button
          variant="ghost"
          size="icon-sm"
          aria-label={`Remove ${source.name}`}
        >
          <RemoveIcon />
        </Button>
      </AlertDialogTrigger>

      <AlertDialogContent>
        <AlertDialogHeader>
          <AlertDialogTitle>
            Remove <span dir="auto">{source.name}</span>?
          </AlertDialogTitle>
          <AlertDialogDescription>
            It comes out of this knowledge base and the agent stops being able
            to look it up. Putting it back means adding it again.
          </AlertDialogDescription>
        </AlertDialogHeader>

        <AlertDialogFooter>
          <AlertDialogCancel>Cancel</AlertDialogCancel>
          <AlertDialogAction variant="destructive" onClick={onRemove}>
            Remove
          </AlertDialogAction>
        </AlertDialogFooter>
      </AlertDialogContent>
    </AlertDialog>
  );
}

function SourceName({
  source,
  onOpenSheet,
}: {
  source: Source;
  onOpenSheet: (id: string) => void;
}) {
  if (isSpreadsheet(source.kind) && source.status === "ready") {
    return (
      <Button
        className="-ms-2.5 h-auto w-fit justify-start text-foreground"
        onClick={() => onOpenSheet(source.id)}
        variant="link"
      >
        <span dir="auto">{source.name}</span>
      </Button>
    );
  }

  if (source.kind === "url" && source.url) {
    return (
      <a
        href={sourceHref(source.url)}
        target="_blank"
        rel="noreferrer"
        className="w-fit font-medium underline-offset-4 hover:underline"
      >
        {source.name}
      </a>
    );
  }

  if (source.kind === "text") {
    return <TextPreview source={source} />;
  }

  return <span className="font-medium">{source.name}</span>;
}

function TextPreview({ source }: { source: Source }) {
  return (
    <Dialog>
      <DialogTrigger asChild>
        <Button
          className="-ms-2.5 h-auto w-fit justify-start text-foreground"
          variant="link"
        >
          {source.name}
        </Button>
      </DialogTrigger>

      <DialogContent className="sm:max-w-md">
        <DialogHeader>
          <DialogTitle>{source.name}</DialogTitle>
          <DialogDescription>
            Added by {source.addedBy} on {source.addedAt}.
          </DialogDescription>
        </DialogHeader>

        <p className="text-sm whitespace-pre-wrap">{source.body}</p>
      </DialogContent>
    </Dialog>
  );
}

function StatusBadge({ source }: { source: Source }) {
  if (source.status === "extracting") {
    return (
      <Badge variant="secondary">
        <Spinner />
        {isSpreadsheet(source.kind) ? "Reading rows" : "Extracting"}
      </Badge>
    );
  }

  if (source.status === "failed") {
    return (
      <Badge variant="destructive">
        <FailedIcon />
        {isSpreadsheet(source.kind) ? "Not added" : "Can't be read"}
      </Badge>
    );
  }

  return (
    <Badge variant="outline">
      <ReadyIcon className="text-success" />
      Ready
    </Badge>
  );
}

